const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: false });
  const context = await browser.newContext();
  const page = await context.newPage();

  const baseDir = '/c/Users/Manu/Projects/pokemon_database_agentic/agents/test_resolver/test_e2e/img/pokemon_e2e_tests';
  const results = {
    test_name: 'pokemon-e2e-tests',
    status: 'passed',
    screenshots: [],
    error: null
  };

  try {
    // Step 1: Verify Home Page Loads
    console.log('Step 1: Verify Home Page Loads');
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('domcontentloaded');

    const title = await page.locator('h1').textContent();
    if (!title.includes('Pokémon Database')) {
      throw new Error(`(Step 1 ❌) Page title does not contain "Pokémon Database". Found: "${title}"`);
    }

    const searchInput = page.locator('.search-input');
    if (!await searchInput.isVisible()) {
      throw new Error('(Step 1 ❌) Search input field is not visible');
    }

    const placeholder = await searchInput.getAttribute('placeholder');
    if (placeholder !== 'Search Pokemon...') {
      throw new Error(`(Step 1 ❌) Search input placeholder incorrect. Expected "Search Pokemon...", got "${placeholder}"`);
    }

    const searchBtn = page.locator('.search-btn');
    if (!await searchBtn.isVisible()) {
      throw new Error('(Step 1 ❌) Search button is not visible');
    }

    const placeholderMsg = page.locator('.search-panel .placeholder-message');
    const placeholderText = await placeholderMsg.textContent();
    if (!placeholderText.includes('Start searching to see results')) {
      throw new Error(`(Step 1 ❌) Placeholder message incorrect. Expected "Start searching to see results", got "${placeholderText}"`);
    }

    const screenshot1 = `${baseDir}/01_home_page.png`;
    await page.screenshot({ path: screenshot1, fullPage: true });
    results.screenshots.push(screenshot1);
    console.log('✅ Step 1 passed');

    // Step 2: Test Basic Pokemon Search
    console.log('Step 2: Test Basic Pokemon Search');
    await searchInput.fill('pikachu');
    await searchBtn.click();

    const firstResult = page.locator('.result-item').first();
    await firstResult.waitFor({ state: 'visible', timeout: 10000 });

    const resultText = await firstResult.textContent();
    if (!resultText.toLowerCase().includes('pikachu')) {
      throw new Error(`(Step 2 ❌) First result does not contain "pikachu". Found: "${resultText}"`);
    }

    const screenshot2 = `${baseDir}/02_pikachu_search_results.png`;
    await page.screenshot({ path: screenshot2, fullPage: true });
    results.screenshots.push(screenshot2);
    console.log('✅ Step 2 passed');

    // Step 3: Test Pokemon Detail View
    console.log('Step 3: Test Pokemon Detail View');
    await firstResult.click();
    await page.waitForTimeout(1000);

    const pokemonName = page.locator('.pokemon-name');
    if (!await pokemonName.isVisible()) {
      throw new Error('(Step 3 ❌) Pokemon detail panel is not visible');
    }

    const nameText = await pokemonName.textContent();
    if (!nameText.toLowerCase().includes('pikachu')) {
      throw new Error(`(Step 3 ❌) Pokemon name does not contain "pikachu". Found: "${nameText}"`);
    }

    const typeBadge = page.locator('.type-badge').first();
    if (!await typeBadge.isVisible()) {
      throw new Error('(Step 3 ❌) Type badge is not visible');
    }

    const pokemonImage = page.locator('.pokemon-image, .pokemon-sprite, img[alt*="pokemon"], img[alt*="sprite"]');
    const imageCount = await pokemonImage.count();
    if (imageCount === 0) {
      throw new Error('(Step 3 ❌) Pokemon sprite/image is not displayed');
    }

    const screenshot3 = `${baseDir}/03_pikachu_details.png`;
    await page.screenshot({ path: screenshot3, fullPage: true });
    results.screenshots.push(screenshot3);
    console.log('✅ Step 3 passed');

    // Step 4: Test Partial Name Search
    console.log('Step 4: Test Partial Name Search');
    await searchInput.clear();
    await searchInput.fill('char');
    await searchBtn.click();
    await page.waitForTimeout(2000);

    const resultCount = await page.locator('.result-item').count();
    if (resultCount <= 1) {
      throw new Error(`(Step 4 ❌) Expected multiple results, got ${resultCount}`);
    }

    const allResults = await page.locator('.result-item').allTextContents();
    for (const result of allResults) {
      if (!result.toLowerCase().includes('char')) {
        throw new Error(`(Step 4 ❌) Result does not contain "char": "${result}"`);
      }
    }

    const screenshot4 = `${baseDir}/04_partial_search_results.png`;
    await page.screenshot({ path: screenshot4, fullPage: true });
    results.screenshots.push(screenshot4);
    console.log('✅ Step 4 passed');

    // Step 5: Test Single Result Auto-Display
    console.log('Step 5: Test Single Result Auto-Display');
    await searchInput.clear();
    await searchInput.fill('ditto');
    await searchBtn.click();
    await page.waitForTimeout(2000);

    const dittoName = page.locator('.pokemon-name');
    await dittoName.waitFor({ state: 'visible', timeout: 10000 });

    const dittoText = await dittoName.textContent();
    if (!dittoText.toLowerCase().includes('ditto')) {
      throw new Error(`(Step 5 ❌) Pokemon name does not contain "ditto". Found: "${dittoText}"`);
    }

    const screenshot5 = `${baseDir}/05_ditto_auto_display.png`;
    await page.screenshot({ path: screenshot5, fullPage: true });
    results.screenshots.push(screenshot5);
    console.log('✅ Step 5 passed');

    // Step 6: Test No Results Scenario
    console.log('Step 6: Test No Results Scenario');
    await searchInput.clear();
    await searchInput.fill('nonexistentpokemon123');
    await searchBtn.click();
    await page.waitForTimeout(2000);

    const noResultsMsg = page.locator('.no-results-message');
    await noResultsMsg.waitFor({ state: 'visible', timeout: 10000 });

    const noResultsText = await noResultsMsg.textContent();
    if (!noResultsText.includes('No results found')) {
      throw new Error(`(Step 6 ❌) Expected "No results found" message, got: "${noResultsText}"`);
    }

    const screenshot6 = `${baseDir}/06_no_results.png`;
    await page.screenshot({ path: screenshot6, fullPage: true });
    results.screenshots.push(screenshot6);
    console.log('✅ Step 6 passed');

    // Step 7: Test Enter Key Search
    console.log('Step 7: Test Enter Key Search');
    await searchInput.clear();
    await searchInput.fill('mewtwo');
    await searchInput.press('Enter');
    await page.waitForTimeout(2000);

    const mewtwoResult = page.locator('.result-item').first();
    await mewtwoResult.waitFor({ state: 'visible', timeout: 10000 });

    const screenshot7 = `${baseDir}/07_enter_key_search.png`;
    await page.screenshot({ path: screenshot7, fullPage: true });
    results.screenshots.push(screenshot7);
    console.log('✅ Step 7 passed');

    // Step 8: Test Clear Button
    console.log('Step 8: Test Clear Button');
    await searchInput.fill('pokemon');
    await page.waitForTimeout(500);

    const clearBtn = page.locator('.clear-btn');
    if (!await clearBtn.isVisible()) {
      throw new Error('(Step 8 ❌) Clear button is not visible');
    }

    await clearBtn.click();
    await page.waitForTimeout(500);

    const inputValue = await searchInput.inputValue();
    if (inputValue !== '') {
      throw new Error(`(Step 8 ❌) Search input should be empty, but contains: "${inputValue}"`);
    }

    const screenshot8 = `${baseDir}/08_clear_button.png`;
    await page.screenshot({ path: screenshot8, fullPage: true });
    results.screenshots.push(screenshot8);
    console.log('✅ Step 8 passed');

    // Step 9: Test Result Selection Highlighting
    console.log('Step 9: Test Result Selection Highlighting');
    await searchInput.fill('eevee');
    await searchBtn.click();
    await page.waitForTimeout(2000);

    const eeveeResult = page.locator('.result-item').first();
    await eeveeResult.waitFor({ state: 'visible', timeout: 10000 });
    await eeveeResult.click();
    await page.waitForTimeout(500);

    const classList = await eeveeResult.getAttribute('class');
    if (!classList.includes('selected')) {
      throw new Error(`(Step 9 ❌) Result does not have "selected" class. Classes: "${classList}"`);
    }

    const screenshot9 = `${baseDir}/09_selected_result.png`;
    await page.screenshot({ path: screenshot9, fullPage: true });
    results.screenshots.push(screenshot9);
    console.log('✅ Step 9 passed');

    // Step 10: Test Pagination
    console.log('Step 10: Test Pagination');
    await searchInput.clear();
    await searchInput.fill('a');
    await searchBtn.click();
    await page.waitForTimeout(2000);

    const paginationResults = page.locator('.result-item').first();
    await paginationResults.waitFor({ state: 'visible', timeout: 10000 });

    const pagination = page.locator('.pagination');
    const isPaginationVisible = await pagination.isVisible().catch(() => false);

    if (isPaginationVisible) {
      const paginationInfo = page.locator('.pagination-info');
      const infoText = await paginationInfo.textContent();
      if (!infoText.includes('Page 1')) {
        throw new Error(`(Step 10 ❌) Pagination info should show "Page 1", got: "${infoText}"`);
      }

      const nextBtn = page.locator('.pagination-btn').last();
      if (!await nextBtn.isVisible()) {
        throw new Error('(Step 10 ❌) Next button is not visible');
      }

      await nextBtn.click();
      await page.waitForTimeout(1000);

      const updatedInfo = await paginationInfo.textContent();
      if (!updatedInfo.includes('Page 2')) {
        throw new Error(`(Step 10 ❌) Pagination info should show "Page 2", got: "${updatedInfo}"`);
      }
      console.log('✅ Step 10 passed (pagination tested)');
    } else {
      console.log('✅ Step 10 passed (pagination not visible - acceptable)');
    }

    const screenshot10 = `${baseDir}/10_pagination.png`;
    await page.screenshot({ path: screenshot10, fullPage: true });
    results.screenshots.push(screenshot10);

  } catch (error) {
    results.status = 'failed';
    results.error = error.message;
    console.error('❌ Test failed:', error.message);
  } finally {
    await browser.close();
    console.log('\n' + JSON.stringify(results, null, 2));
  }
})();

